import { useEffect, useMemo, useState } from 'react';
import transform from '@diplodoc/transform';
import { YfmStaticView, type MarkupString, type RenderPreviewParams } from '@gravity-ui/markdown-editor';

const RENDER_DEBOUNCE_MS = 150;

type MarkdownPreviewProps = {
    getValue: () => MarkupString;
    md: RenderPreviewParams['md'];
};

function renderMarkdown(markup: MarkupString, md: RenderPreviewParams['md']): string {
    return transform(markup, {
        // Plain markdown only: no YFM plugins and no liquid templating,
        // so the preview matches what the 'default' editor preset produces.
        plugins: [],
        disableLiquid: true,
        allowHTML: md.html ?? false,
        needToSanitizeHtml: true,
        breaks: md.breaks,
        linkify: md.linkify,
        linkifyTlds: md.linkifyTlds,
        // Adds data-line attributes used by the editor for scroll sync in split mode.
        lineNumbers: true,
    } as Parameters<typeof transform>[1]).result.html;
}

/**
 * Preview for the markup mode of the editor (split view and full-screen preview).
 * The editor re-renders this component on each change, so we debounce the transform.
 */
export function MarkdownPreview({ getValue, md }: MarkdownPreviewProps) {
    const markup = getValue();
    const [html, setHtml] = useState(() => renderMarkdown(markup, md));

    const options = useMemo(() => md, [md.html, md.breaks, md.linkify, md.linkifyTlds]);

    useEffect(() => {
        const timer = setTimeout(() => setHtml(renderMarkdown(markup, options)), RENDER_DEBOUNCE_MS);
        return () => clearTimeout(timer);
    }, [markup, options]);

    return <YfmStaticView html={html} noListReset />;
}

