// @vitest-environment jsdom
import { test, expect } from 'vitest';
import React, { act } from 'react';
import { createRoot } from 'react-dom/client';
import { ThemeProvider, Toaster, ToasterProvider } from '@gravity-ui/uikit';
import type { MarkdownEditorInstance } from '@gravity-ui/markdown-editor';
import { MarkdownField, useMarkdownFieldEditor } from './MarkdownField';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
(window as any).ResizeObserver ??= class { observe() {} unobserve() {} disconnect() {} };
(window as any).matchMedia ??= () => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });
document.createRange = () => { const r = new Range(); (r as any).getBoundingClientRect = () => ({}); (r as any).getClientRects = () => ({ length: 0, item: () => null, [Symbol.iterator]: [][Symbol.iterator] }); return r; };

let editor!: MarkdownEditorInstance;
let changes = 0;
function Harness() {
  editor = useMarkdownFieldEditor({});
  return <MarkdownField editor={editor} label="L" onChange={React.useCallback(() => { changes++; }, [])} />;
}

function typeText(view: any, text: string) {
  for (const ch of text) {
    const { from, to } = view.state.selection;
    const handled = view.someProp('handleTextInput', (f: any) => f(view, from, to, ch, () => view.state.tr.insertText(ch, from, to)));
    if (!handled) view.dispatch(view.state.tr.insertText(ch, from, to));
  }
}

test('markdown typed in wysiwyg is formatted immediately; markup mode shows live preview', async () => {
  const c = document.createElement('div'); document.body.appendChild(c);
  await act(async () => { createRoot(c).render(<ThemeProvider theme="light"><ToasterProvider toaster={new Toaster()}><Harness /></ToasterProvider></ThemeProvider>); });
  const pm = c.querySelector('.ProseMirror') as any;
  const view = pm.pmViewDesc.view;
  await act(async () => { typeText(view, '# Заголовок'); });
  expect(pm.querySelector('h1')?.textContent).toBe('Заголовок');
  await act(async () => { view.dispatch(view.state.tr.insertText('', view.state.doc.content.size)); editor.append('para'); });
  await act(async () => { editor.moveCursor('end'); typeText(view, ' и **жирный** и *курсив* '); });
  console.log('WYSIWYG DOM:', pm.innerHTML.replace(/<div class="g-md-placeholder.*?<\/div>/g, ''));
  expect(pm.querySelector('strong')?.textContent).toBe('жирный');
  expect(pm.querySelector('em')?.textContent).toBe('курсив');
  console.log('markdown value:', JSON.stringify(editor.getValue()));
  expect(changes).toBeGreaterThan(0);

  await act(async () => { editor.setEditorMode('markup'); });
  await act(async () => { await new Promise(r => setTimeout(r, 300)); });
  const preview = c.querySelector('.yfm');
  console.log('PREVIEW:', preview?.innerHTML);
  expect(preview?.querySelector('strong')?.textContent).toBe('жирный');
  expect(preview?.querySelector('h1')).toBeTruthy();
});
EOF
